import unreal
rows=[]
for obj in unreal.ObjectIterator(unreal.NiagaraScript):
    name=obj.get_name()
    path=obj.get_path_name()
    if 'SSPR' in name or 'NS_SSPR_ProjTest' in path:
        source=None
        try: source=obj.get_editor_property('source')
        except Exception: pass
        rows.append((name,path,source.get_path_name() if source else None,obj.get_outer().get_path_name() if obj.get_outer() else None))
for row in rows: print('SCRIPT=' + repr(row))
print('COUNT=' + str(len(rows)))
